INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Masalah: Ingin Ngobrol Bahasa Arab tapi Cuma Tahu As-salamu'alaikum$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Banyak orang Indonesia bisa membaca Al-Qur'an tetapi kaku saat harus berbicara bahasa Arab sehari-hari. Padahal pola percakapannya sederhana dan berulang: sapaan, kabar, keperluan, lalu pamit. Dengan 20-30 kalimat inti, kamu sudah bisa menjalani percakapan dasar di pasar, restoran, atau saat umrah.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Penjelasan: Tiga Pola Percakapan Inti$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Percakapan sehari-hari bahasa Arab berputar pada tiga pola: (1) sapaan dan kabar — As-salamu'alaikum, kaifa haluk (apa kabarmu); (2) keperluan — uridu (saya mau) atau kam (berapa); (3) penutup — ma'a as-salamah (selamat jalan). Bahasa Arab membedakan kamu laki-laki (anta) dan perempuan (anti), jadi pilih kata ganti yang tepat.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Alat yang Perlu Disiapkan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', ARRAY[$$Buku catatan kecil untuk kosakata harian$$, $$Aplikasi kamus Arab-Indonesia (offline)$$, $$Rekaman/audio percakapan untuk latihan pelafalan$$, $$Teman latihan atau cermin untuk praktik berbicara$$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Langkah-langkah: Dari Sapaan sampai Pamit$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', ARRAY[$$Sapaan & perkenalan: As-salamu'alaikum, sabah al-khair, ismi... (nama saya...), min aina anta? (kamu dari mana?) — ucapkan 10x tiap frasa$$, $$Tanya kabar: kaifa haluk/haluki? Jawab: ana bi khair, alhamdulillah$$, $$Keperluan: kam tsaman hadza? (berapa harga ini?), uridu hadza (saya mau ini), al-hisab min fadlik (minta billnya)$$, $$Penutup: syukran (terima kasih, jawabannya 'afwan), ma'a as-salamah (selamat jalan), ila al-liqa' (sampai jumpa lagi)$$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Risiko dan Kesalahan Umum$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', ARRAY[$$Tertukar anta/anti (laki-laki/perempuan) — perhatikan lawan bicara$$, $$Pengucapan huruf 'ain dan ha' yang asal-asalan mengubah arti kata$$, $$Terlalu fokus tata bahasa sampai tidak berani bicara — keberanian dulu, akurasi menyusul$$, $$Menghafal tanpa praktik: kosakata hilang dalam seminggu tanpa dipakai$$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Penyelesaian: Rencana 14 Hari$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $$Target realistis: hari 1-3 sapaan, hari 4-7 kabar dan perkenalan, hari 8-11 belanja dan makan, hari 12-14 latihan percakapan penuh 5 menit tanpa berhenti. Rekam suaramu di hari 1 dan hari 14, bandingkan — kemajuan pasti terdengar.$$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Masalah: Sepatu Tiba-tiba Sempit di Sore Hari$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Kaki yang membengkak di sore hari setelah seharian duduk atau berdiri adalah keluhan umum. Seringkali ini normal dan hilang setelah istirahat. Namun bengkak yang menetap, nyeri, atau hanya di satu kaki bisa menandakan masalah pembuluh darah, jantung, ginjal, atau hati. Mengenali bedanya penting agar tidak terlambat bertindak.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Penjelasan: Mengapa Kaki Bisa Bengkak$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Bengkak (edema) terjadi ketika cairan menumpuk di jaringan. Penyebab ringan: duduk/berdiri terlalu lama, cuaca panas, terlalu banyak garam, kehamilan, atau efek obat tertentu. Penyebab yang perlu diwaspadai: gagal jantung, penyakit ginjal, gangguan hati, penggumpalan darah di kaki (DVT), atau infeksi. Artikel ini informasi umum, bukan pengganti nasihat medis.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Alat dan Persiapan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', ARRAY[$$Bantal untuk meninggikan kaki$$, $$Air hangat/dingin dan handuk untuk kompres$$, $$Catatan: kapan bengkak muncul, satu/dua kaki, ada nyeri atau tidak$$, $$Daftar obat yang sedang dikonsumsi (beberapa obat menyebabkan bengkak)$$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Langkah-langkah Perawatan Mandiri$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', ARRAY[$$Angkat kaki lebih tinggi dari jantung 15-30 menit, 3-4 kali sehari — gravitasi membantu cairan kembali ke peredaran$$, $$Jangan duduk/berdiri diam lebih dari 1-2 jam; gerakkan pergelangan kaki dan jalan sebentar tiap jam$$, $$Kurangi makanan asin dan olahan; minum air putih cukup$$, $$Kompres dingin 10-15 menit untuk bengkak akibat lelah; pijat lembut dari kaki ke arah lutut$$, $$Catat pola bengkak selama 3-7 hari sebagai bahan konsultasi dokter bila perlu$$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Risiko: Tanda Bahaya — Segera ke Dokter atau IGD$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', ARRAY[$$Bengkak hanya di SATU kaki disertai nyeri, kemerahan, atau hangat: curiga penggumpalan darah (DVT)$$, $$Bengkak disertai sesak napas atau nyeri dada: kemungkinan masalah jantung$$, $$Bengkak mendadak di wajah/tangan/kaki disertai sesak: kemungkinan alergi berat$$, $$Bengkak tidak membaik setelah 3-5 hari perawatan mandiri$$, $$Luka di kaki bengkak yang tidak sembuh, terutama pada penderita diabetes$$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Penyelesaian: Kapan Cukup Perawatan Mandiri$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $$Jika bengkak ringan, di dua kaki, muncul setelah aktivitas, dan membaik dengan istirahat serta kaki ditinggikan — cukup perawatan mandiri dan perbaiki kebiasaan. Jika ada satu saja tanda bahaya di atas, atau bengkak menetap, konsultasikan ke dokter. Jangan menunda karena bengkak bisa jadi petunjuk awal penyakit serius yang masih mudah ditangani.$$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Hutan Hujan: Definisi dan Cirinya$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Hutan hujan tropis adalah hutan dengan curah hujan sangat tinggi (lebih dari 2.000 mm per tahun) dan suhu hangat sepanjang tahun. Kanopinya berlapis-lapis, dari lantai hutan yang gelap hingga tajuk setinggi 40-60 meter. Meski hanya menutupi sekitar 6 persen permukaan daratan Bumi, hutan hujan menyimpan lebih dari separuh spesies tumbuhan dan hewan dunia.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Amazon dan Kongo: Dua Raksasa Terbesar$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Hutan Amazon di Amerika Selatan adalah yang terbesar — sekitar 5,5 juta kilometer persegi di 9 negara, menyimpan sekitar 10 persen spesies yang dikenal dunia. Terbesar kedua adalah Cekungan Kongo di Afrika Tengah (sekitar 3,7 juta km persegi), rumah gorila, bonobo, dan okapi, sekaligus penyerap karbon raksasa penyeimbang iklim Afrika.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Hutan Hujan Asia Tenggara: Termasuk Indonesia$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $$Hutan hujan Asia Tenggara — termasuk Sumatra, Kalimantan, dan Papua — termasuk yang tertua di dunia (lebih dari 100 juta tahun, lebih tua dari Amazon). Indonesia adalah rumah bagi orangutan, harimau Sumatra, badak Jawa, dan komodo. Sekitar seperempat obat modern berasal dari tumbuhan hutan hujan, dan kurang dari 1 persen spesiesnya yang sudah diteliti.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Ancaman: Deforestasi dan Titik Kritis$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Penyebab utama hilangnya hutan hujan: pembukaan lahan sawit dan kedelai, peternakan, penebangan liar, pertambangan, dan kebakaran yang makin sering akibat perubahan iklim. Amazon telah kehilangan sekitar 17 persen luasnya; ilmuwan khawatir jika mencapai 20-25 persen, hutan bisa berubah menjadi sabana (tipping point) yang melepas karbon raksasa.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Menjaga Paru-paru Bumi$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Upaya penyelamatan meliputi kawasan konservasi, sertifikasi produk lestari, penegakan hukum, restorasi hutan, dan pendanaan internasional. Indonesia pernah mencatat penurunan deforestasi berkat moratorium dan penegakan hukum. Peran konsumen nyata: memilih produk bersertifikat lestari ikut menekan permintaan dari sumber perusak hutan — menjaga hutan hujan adalah urusan kelangsungan hidup manusia.$$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Apa Itu E-commerce$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$E-commerce (perdagangan elektronik) adalah jual beli barang dan jasa melalui internet. Bentuknya beragam: marketplace (banyak penjual dalam satu platform), toko online mandiri, social commerce (jualan lewat media sosial), hingga live shopping. Di Indonesia, e-commerce tumbuh menjadi salah satu yang terbesar di Asia Tenggara.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Sejarah Singkat dan Cara Kerja$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$E-commerce modern lahir pada 1990-an: Amazon (1994) mulai dari toko buku online, eBay (1995) dari lelang barang bekas; di Indonesia era marketplace meledak pada 2010-an seiring smartphone murah. Di balik tombol 'beli' ada sistem kompleks: katalog, payment gateway, gudang dan stok, logistik, hingga layanan retur — plus algoritma rekomendasi berbasis data perilaku belanja.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Dampak Positif bagi Ekonomi$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $$E-commerce membuka pasar nasional bagi UMKM di daerah terpencil — pengrajin desa bisa menjual ke seluruh Indonesia. Ia menciptakan jutaan lapangan kerja: kurir, operator gudang, admin toko online, kreator konten. Harga menjadi lebih transparan karena pembeli mudah membandingkan antar penjual.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Sisi Gelapnya$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Tidak semuanya indah: barang palsu dan penipuan, perang harga yang mematikan UMKM kecil, ketergantungan penjual pada algoritma platform, target kerja ketat bagi pekerja logistik, budaya konsumtif akibat kemudahan belanja, dan data pribadi pembeli yang menjadi komoditas profil iklan.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Tren dan Masa Depan: Live Shopping hingga AI$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Tren terbesar saat ini adalah live shopping — penjual mendemonstrasikan produk sambil berinteraksi langsung dengan penonton, menggabungkan hiburan dan belanja. Masa depan mengarah ke rekomendasi AI yang makin personal, logistik makin cepat, dan integrasi online-offline. Regulasi perlindungan konsumen akan menentukan apakah revolusi ini menguntungkan semua pihak atau hanya segelintir platform raksasa.$$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Tujuan Pembelajaran$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 1, jsonb_build_object('items', ARRAY[$$Menjelaskan sifat-sifat cahaya (merambat lurus, dapat dipantulkan, dibiaskan, diuraikan)$$, $$Membedakan pemantulan teratur dan baur serta hukum pemantulan$$, $$Menjelaskan pembiasan cahaya dan pembentukan bayangan pada cermin dan lensa$$, $$Menjelaskan prinsip kerja alat optik: kamera, lup, mikroskop, teleskop$$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Sifat-sifat Cahaya$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Cahaya adalah gelombang elektromagnetik yang dapat dilihat mata. Sifat utamanya: (1) merambat lurus — buktinya bayangan benda; (2) dapat dipantulkan (refleksi); (3) dapat dibiaskan (refraksi) saat melewati dua medium berbeda; (4) dapat diuraikan (dispersi) menjadi warna pelangi; (5) menembus benda bening. Kecepatannya di ruang hampa sekitar 300.000 km/detik — tercepat di alam semesta.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Pemantulan dan Cermin$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $$Hukum pemantulan: sudut datang = sudut pantul. Cermin datar menghasilkan bayangan maya, tegak, sama besar. Cermin cekung mengumpulkan cahaya (dipakai pada reflektor senter dan teleskop); cermin cembung menyebarkan cahaya sehingga bayangan selalu maya, tegak, diperkecil — dipakai pada kaca spion dan cermin tikungan jalan karena medan pandangnya luas.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Pembiasan dan Lensa$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Pembiasan terjadi saat cahaya melewati batas dua medium berbeda kerapatannya — sedotan terlihat patah di dalam gelas. Lensa cembung mengumpulkan cahaya (lup, kamera); lensa cekung menyebarkan cahaya (kacamata minus untuk rabun jauh). Rumus lensa: 1/f = 1/s + 1/s'. Contoh: benda di ruang II lensa cembung menghasilkan bayangan nyata, terbalik, diperbesar — prinsip proyektor.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Alat Optik: Mata, Kamera, Lup, Mikroskop, Teleskop$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Mata memakai lensa cembung yang memfokuskan cahaya ke retina; kamera menirunya dengan diafragma seperti pupil. Lup adalah lensa cembung sederhana (perbesaran 2-20x). Mikroskop memakai lensa objektif + okuler hingga ratusan kali perbesaran. Teleskop memakai objektif berdiameter besar untuk mengumpulkan cahaya bintang yang redup. Rabun jauh dikoreksi lensa cekung, rabun dekat dengan lensa cembung.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Latihan Soal dan Kunci Jawaban$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', ARRAY[$$Soal 1: Sebutkan 4 sifat cahaya beserta contohnya! → Merambat lurus (bayangan), dipantulkan (cermin), dibiaskan (sedotan patah), diuraikan (pelangi).$$, $$Soal 2: Benda 15 cm di depan cermin cekung (f = 10 cm). Di mana bayangan? → 1/10 = 1/15 + 1/s' → s' = 30 cm; nyata, terbalik, diperbesar.$$, $$Soal 3: Mengapa spion memakai cermin cembung? → Medan pandang lebih luas sehingga pengendara melihat area lebih besar di belakang.$$]));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Tujuan Pembelajaran$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 1, jsonb_build_object('items', ARRAY[$$Melakukan gerakan pemanasan dengan benar sebelum berolahraga$$, $$Mempraktikkan gerakan senam lantai sederhana (mengguling, melompat, keseimbangan)$$, $$Melakukan pendinginan setelah berolahraga$$, $$Menunjukkan sikap disiplin, berani, dan menjaga keselamatan$$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Apa Itu Senam?$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Senam adalah olahraga yang melatih kelenturan, kekuatan, dan keseimbangan tubuh lewat gerakan-gerakan yang teratur. Senam membuat badan lentur, otot kuat, dan postur tegak. Atlet senam Indonesia pernah meraih medali di SEA Games dan Asian Games — kamu pun bisa mulai dari gerakan dasar seperti yang kita pelajari hari ini!$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Pemanasan: Wajib Sebelum Bergerak$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $$Pemanasan menyiapkan otot dan jantung agar tidak cedera. Lakukan 5-10 menit: (1) lari kecil di tempat 2 menit, (2) putar kepala, bahu, pinggang masing-masing 8 kali, (3) ayun lengan ke depan-belakang, (4) tekuk lutut dan lompat kecil 10 kali. Badan yang hangat ditandai keringat tipis dan napas sedikit cepat.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Gerakan Inti: Mengguling, Melompat, Keseimbangan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Roll depan di atas matras: jongkok, tangan menempel matras, dagu menempel dada, tolak kaki dan gulingkan badan — dagu selalu menempel dada agar kepala aman. Lompat bintang: lompat sambil membuka tangan-kaki seperti bintang, mendarat dengan lutut ditekuk. Berdiri satu kaki 10 detik tiap kaki, lalu coba berjalan di atas garis lurus seperti balok titian.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Pendinginan dan Keselamatan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', ARRAY[$$Pendinginan 5 menit: raih ujung kaki 15 detik, tarik lengan ke dada, duduk tempelkan telapak kaki, bernapas dalam 5x$$, $$Selalu pakai matras untuk gerakan mengguling$$, $$Lepas jam tangan dan benda keras lainnya$$, $$Jangan bercanda atau mendorong teman saat berlatih$$, $$Berhenti dan lapor guru jika pusing, nyeri, atau sesak$$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Permainan, Latihan Mandiri, dan Rangkuman$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', ARRAY[$$Permainan estafet gerakan: tiap regu bergantian melakukan roll depan / lompat bintang / berdiri satu kaki — tercepat dan benar menang$$, $$Latihan mandiri: pemanasan 5 menit tiap pagi; berdiri satu kaki 30 detik sambil gosok gigi; peregangan sebelum tidur$$, $$Rangkuman: senam dasar = pemanasan + gerakan inti (mengguling, melompat, keseimbangan) + pendinginan. Tertib, aman, dan rutin — tubuh lentur dan kuat adalah bekal semua olahraga.$$]));
